private static void EnsureOverFrameSubPercent(DataTable dt)
{
    if (dt == null || dt.Columns.Contains("OverFrameSubPercent"))
        return;
    if (!dt.Columns.Contains("OverFrameSub") || !dt.Columns.Contains("SalaryRatio"))
        return;

    dt.Columns.Add("OverFrameSubPercent", typeof(decimal));
    for (int i = 0; i < dt.Rows.Count; i++)
    {
        decimal ratio = ToDecimal(dt.Rows[i]["SalaryRatio"]);
        decimal overFrame = ToDecimal(dt.Rows[i]["OverFrameSub"]);
        if (ratio == 0)
            dt.Rows[i]["OverFrameSubPercent"] = 0m;
        else
            dt.Rows[i]["OverFrameSubPercent"] = Math.Round(overFrame * 100m / ratio, 0, MidpointRounding.AwayFromZero);
    }
}

private static decimal ToDecimal(object value)
{
    if (value == null || value == DBNull.Value)
        return 0m;
    decimal d;
    if (decimal.TryParse(value.ToString(), NumberStyles.Any, CultureInfo.InvariantCulture, out d))
        return d;
    if (decimal.TryParse(value.ToString(), NumberStyles.Any, CultureInfo.CurrentCulture, out d))
        return d;
    return 0m;
}

