        }

        public void BindForEmployee(long employeeId)
        {
            DataTable dt = null;
            try
            {
                dt = employeeDao.GetDataTable(StoreSummarySalaryForEmployee, "@EmployeeID", employeeId);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabPhieuLuong.BindForEmployee: " + ex.Message);
            }

            if (dt == null)
                dt = new DataTable();

            EnsureBoundColumns(dt);

            gvPhieuLuong.DataSource = dt;
            gvPhieuLuong.DataBind();
        }

        protected object GetRowValue(object dataItem, string fieldName)
        {
            DataRowView row = dataItem as DataRowView;
            if (row == null || row.Row == null || row.Row.Table == null)
                return null;
            if (!row.Row.Table.Columns.Contains(fieldName))
                return null;
            return row[fieldName];
        }

        protected string FormatMonthField(object dataItem, string fieldName)
        {
            object value = GetRowValue(dataItem, fieldName);
            if (value == null || value == DBNull.Value)
                return string.Empty;

            DateTime d;
            if (value is DateTime)
                d = (DateTime)value;
            else if (!DateTime.TryParse(value.ToString(), out d))
                return string.Empty;

            return d.ToString("MM/yyyy");
        }

        protected string FormatDecimalField(object dataItem, string fieldName)
        {
            return FormatDecimal(GetRowValue(dataItem, fieldName));
        }

        protected string FormatMoneyField(object dataItem, string fieldName)
        {
            return FormatMoney(GetRowValue(dataItem, fieldName));
        }

        protected string FormatMoney(object value)
        {
            if (value == null || value == DBNull.Value)
                return "";
            decimal d;
            if (!decimal.TryParse(value.ToString(), NumberStyles.Any, CultureInfo.InvariantCulture, out d))
            {
                if (!decimal.TryParse(value.ToString(), NumberStyles.Any, CultureInfo.CurrentCulture, out d))
                    return value.ToString();
            }
            return d.ToString("N0", CultureInfo.InvariantCulture);
        }

        protected string FormatDecimal(object value)
        {
            if (value == null || value == DBNull.Value)
                return "";
            decimal d;
            if (!decimal.TryParse(value.ToString(), NumberStyles.Any, CultureInfo.InvariantCulture, out d))
            {
                if (!decimal.TryParse(value.ToString(), NumberStyles.Any, CultureInfo.CurrentCulture, out d))
                    return value.ToString();
            }
            return d.ToString("N2", CultureInfo.InvariantCulture);
        }

        private static void EnsureBoundColumns(DataTable dt)
        {
            if (dt == null)
                return;

            string[] cols = new string[] { "PositionID", "SalaryQuotaCode", "SalaryQuotaName", "SalaryLevel", "Description" };
            for (int i = 0; i < cols.Length; i++)
            {
                if (!dt.Columns.Contains(cols[i]))
                    dt.Columns.Add(cols[i]);
            }
        }
    }
}

